def firstSharedNode(succ, headA, headB):
    def entry(h):
        slow = fast = h
        while fast != -1 and succ[fast] != -1:
            slow = succ[slow]
            fast = succ[succ[fast]]
            if slow == fast:
                slow = h
                while slow != fast:
                    slow = succ[slow]
                    fast = succ[fast]
                return slow
        return -1

    def dist(h, stop):
        d = 0
        while h != stop:
            h = succ[h]
            d += 1
        return d

    def merge(a, b, stop):
        la, lb = dist(a, stop), dist(b, stop)
        while la > lb:
            a = succ[a]
            la -= 1
        while lb > la:
            b = succ[b]
            lb -= 1
        while a != b:
            a = succ[a]
            b = succ[b]
        return a

    ea, eb = entry(headA), entry(headB)
    if (ea == -1) != (eb == -1):
        return -1
    if ea == -1:
        return merge(headA, headB, -1)
    if ea == eb:
        return merge(headA, headB, ea)
    cur = succ[ea]
    while cur != ea:
        if cur == eb:
            return ea
        cur = succ[cur]
    return -1
